  ('bi-group', 'BI Group', null, null, 'https://bi.group', '360', 'Строит жильё в Астане, Алматы, Шымкенте, Атырау и Караганде. Проекты в Астане оформлены на ТОО «BI Development Astana» (БИН 130940009587).', null, 'https://bi.group/ru/special/kvartiry', '2026-10-17'),
  ('bazis-a', 'BAZIS-A', '960340000376', null, 'https://bazis.kz', null, 'Строит жилые комплексы в Алматы, Астане, Шымкенте и Атырау. Застройщик в реестре — ТОО «BAZIS-A Corp.».', null, 'https://sales.bazis.kz/', '2026-10-17')
